public with sharing class ExchangeRateClient {
    public class ExchangeRateException extends Exception {
    }

    private static final String NAMED_CREDENTIAL_ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Pattern CURRENCY_CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String normalizedBase = normalizeAndValidateCurrencyCode(baseCurrency, 'base currency');

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String quoteCurrency : quoteCurrencies) {
            normalizedQuotes.add(normalizeAndValidateCurrencyCode(quoteCurrency, 'quote currency'));
        }

        if (normalizedQuotes.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }

        List<String> sortedQuotes = new List<String>(normalizedQuotes);
        sortedQuotes.sort();

        String endpoint = NAMED_CREDENTIAL_ENDPOINT
            + '?base=' + EncodingUtil.urlEncode(normalizedBase, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(String.join(sortedQuotes, ','), 'UTF-8');

        HttpRequest request = new HttpRequest();
        request.setEndpoint(endpoint);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');

        Http http = new Http();
        HttpResponse response = http.send(request);

        if (response.getStatusCode() == 503) {
            response = http.send(request);
        }

        Integer statusCode = response.getStatusCode();
        if (statusCode != 200) {
            throw new ExchangeRateException('Exchange rate request failed with status code ' + statusCode + '.');
        }

        return parseRates(response.getBody(), normalizedQuotes);
    }

    private static String normalizeAndValidateCurrencyCode(String currencyCode, String fieldName) {
        String normalized = currencyCode == null ? null : currencyCode.trim().toUpperCase();

        if (String.isBlank(normalized) || !CURRENCY_CODE_PATTERN.matcher(normalized).matches()) {
            throw new ExchangeRateException('Invalid ' + fieldName + ': currency code must be exactly three letters A-Z.');
        }

        return normalized;
    }

    private static Map<String, Decimal> parseRates(String responseBody, Set<String> requestedCodes) {
        try {
            Object parsedBody = JSON.deserializeUntyped(responseBody);
            if (!(parsedBody instanceof Map<String, Object>)) {
                throw new ExchangeRateException('Exchange rate response body could not be parsed.');
            }

            Map<String, Object> body = (Map<String, Object>) parsedBody;
            Object ratesValue = body.get('rates');
            if (!(ratesValue instanceof Map<String, Object>)) {
                throw new ExchangeRateException('Exchange rate response is missing rates.');
            }

            Map<String, Object> rates = (Map<String, Object>) ratesValue;
            Map<String, Decimal> requestedRates = new Map<String, Decimal>();

            for (String code : requestedCodes) {
                if (!rates.containsKey(code) || rates.get(code) == null) {
                    throw new ExchangeRateException('Exchange rate response is missing rate for ' + code + '.');
                }

                Object rawRate = rates.get(code);
                if (!(rawRate instanceof Decimal)) {
                    throw new ExchangeRateException('Exchange rate for ' + code + ' is not numeric.');
                }

                requestedRates.put(code, (Decimal) rawRate);
            }

            return requestedRates;
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Exchange rate response body could not be parsed.');
        }
    }
}
