public with sharing class PaymentTerms {
    private static final Integer MAX_NET_DAYS = 180;
    private static final Pattern NET_TERMS_PATTERN = Pattern.compile('(?i)^NET\\s*(\\d{1,3})$');

    public static Integer parseNetDays(String terms) {
        String trimmedTerms = terms == null ? null : terms.trim();

        if (trimmedTerms == null || trimmedTerms == '') {
            throw new UnsupportedTermsException('Unsupported payment terms: ' + String.valueOf(terms));
        }

        if (trimmedTerms.equalsIgnoreCase('DUE ON RECEIPT')) {
            return 0;
        }

        Matcher netTermsMatcher = NET_TERMS_PATTERN.matcher(trimmedTerms);
        if (netTermsMatcher.matches()) {
            Integer netDays = Integer.valueOf(netTermsMatcher.group(1));

            if (netDays > MAX_NET_DAYS) {
                throw new TermsOutOfRangeException('Net days out of range: ' + netDays);
            }

            return netDays;
        }

        throw new UnsupportedTermsException('Unsupported payment terms: ' + String.valueOf(terms));
    }

    public static Date dueDate(Date invoiceDate, String terms) {
        Integer netDays = parseNetDays(terms);
        return invoiceDate.addDays(netDays);
    }
}
