public with sharing class RecordSearchService {
    public class SearchException extends Exception {
    }

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object API name is required.');
            }
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('At least one field is required.');
            }
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }

            Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
            Schema.SObjectType objectType = globalDescribe.get(objectApiName.toLowerCase());
            if (objectType == null) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
            if (!objectDescribe.isAccessible()) {
                throw new SearchException('The running user cannot read object: ' + objectDescribe.getName());
            }

            Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();

            Set<String> selectedFieldNamesLower = new Set<String>();
            List<String> selectedFieldNames = new List<String>();

            for (String requestedField : fields) {
                Schema.DescribeFieldResult fieldDescribe = getFieldDescribe(fieldMap, requestedField, 'Selected field');

                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException('The running user cannot read field: ' + requestedField);
                }

                String canonicalFieldName = fieldDescribe.getName();
                String lowerFieldName = canonicalFieldName.toLowerCase();

                if (lowerFieldName == 'id') {
                    continue;
                }

                if (!selectedFieldNamesLower.contains(lowerFieldName)) {
                    selectedFieldNamesLower.add(lowerFieldName);
                    selectedFieldNames.add(canonicalFieldName);
                }
            }

            Map<String, Object> bindValues = new Map<String, Object>();
            List<String> whereClauses = new List<String>();

            if (filters != null && !filters.isEmpty()) {
                Integer filterIndex = 0;

                for (String filterFieldName : filters.keySet()) {
                    Schema.DescribeFieldResult fieldDescribe = getFieldDescribe(fieldMap, filterFieldName, 'Filter field');

                    if (!fieldDescribe.isAccessible()) {
                        throw new SearchException('The running user cannot read filter field: ' + filterFieldName);
                    }
                    if (!fieldDescribe.isFilterable()) {
                        throw new SearchException('Field cannot be filtered: ' + filterFieldName);
                    }

                    String bindName = 'filterValue' + String.valueOf(filterIndex);
                    whereClauses.add(fieldDescribe.getName() + ' = :' + bindName);
                    bindValues.put(bindName, filters.get(filterFieldName));
                    filterIndex++;
                }
            }

            String orderByClause = '';
            if (!String.isBlank(orderByField)) {
                Schema.DescribeFieldResult fieldDescribe = getFieldDescribe(fieldMap, orderByField, 'Order-by field');

                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException('The running user cannot read order-by field: ' + orderByField);
                }
                if (!fieldDescribe.isSortable()) {
                    throw new SearchException('Field cannot be sorted: ' + orderByField);
                }

                orderByClause = ' ORDER BY ' + fieldDescribe.getName() + ' ASC';
            }

            List<String> queryFields = new List<String>{ 'Id' };
            queryFields.addAll(selectedFieldNames);

            String soql = 'SELECT ' + String.join(queryFields, ', ')
                + ' FROM ' + objectDescribe.getName();

            if (!whereClauses.isEmpty()) {
                soql += ' WHERE ' + String.join(whereClauses, ' AND ');
            }

            soql += orderByClause;
            soql += ' LIMIT :limitRows';

            bindValues.put('limitRows', maxRows);

            return Database.queryWithBinds(
                soql,
                bindValues,
                AccessLevel.USER_MODE
            );
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException(e.getMessage());
        }
    }

    private static Schema.DescribeFieldResult getFieldDescribe(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName,
        String label
    ) {
        if (String.isBlank(fieldName)) {
            throw new SearchException(label + ' is required.');
        }

        Schema.SObjectField fieldToken = fieldMap.get(fieldName.toLowerCase());
        if (fieldToken == null) {
            throw new SearchException(label + ' does not exist: ' + fieldName);
        }

        return fieldToken.getDescribe();
    }
}
