public with sharing class OrderPayloadParser {
    public class PayloadException extends Exception {
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        try {
            if (String.isBlank(body)) {
                throw new PayloadException('Request body is required.');
            }

            Object rawPayload = JSON.deserializeUntyped(body);
            if (!(rawPayload instanceof Map<String, Object>)) {
                throw new PayloadException('JSON payload must be an object.');
            }

            Map<String, Object> payload = (Map<String, Object>) rawPayload;

            Order order = new Order();
            order.orderNumber = getString(payload, 'number');
            if (String.isBlank(order.orderNumber)) {
                throw new PayloadException('Order number is required.');
            }

            String dateValue = getString(payload, 'date');
            if (!String.isBlank(dateValue)) {
                order.orderDate = Date.valueOf(dateValue);
            }

            order.currencyCode = getString(payload, 'currency');
            order.customerEmail = null;
            order.lines = new List<Line>();
            order.total = 0;

            Object customerValue = payload.get('customer');
            if (customerValue instanceof Map<String, Object>) {
                Map<String, Object> customer = (Map<String, Object>) customerValue;
                order.customerEmail = getString(customer, 'email');
            }

            Object linesValue = payload.get('lines');
            if (linesValue != null) {
                if (linesValue instanceof List<Object>) {
                    for (Object lineValue : (List<Object>) linesValue) {
                        if (!(lineValue instanceof Map<String, Object>)) {
                            throw new PayloadException('Each line must be an object.');
                        }

                        Line line = parseLine((Map<String, Object>) lineValue);
                        order.lines.add(line);
                        order.total += line.lineTotal;
                    }
                } else {
                    throw new PayloadException('Lines must be an array.');
                }
            }

            order.total = order.total.setScale(2, RoundingMode.HALF_UP);
            return order;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException(e.getMessage());
        }
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> acknowledgement = new Map<String, Object>();
        acknowledgement.put('number', order == null ? null : order.orderNumber);
        acknowledgement.put('status', 'RECEIVED');
        acknowledgement.put('lineCount', order == null || order.lines == null ? 0 : order.lines.size());
        acknowledgement.put('total', order == null || order.total == null ? 0 : order.total);
        return JSON.serialize(acknowledgement);
    }

    private static Line parseLine(Map<String, Object> linePayload) {
        Line line = new Line();

        line.sku = getString(linePayload, 'sku');
        if (String.isBlank(line.sku)) {
            throw new PayloadException('Line sku is required.');
        }

        line.quantity = getInteger(linePayload, 'quantity');
        if (line.quantity == null || line.quantity <= 0) {
            throw new PayloadException('Line quantity must be positive.');
        }

        line.unitPrice = getDecimal(linePayload, 'unitPrice');
        if (line.unitPrice == null || line.unitPrice < 0) {
            throw new PayloadException('Line unitPrice must be zero or positive.');
        }

        line.discount = getDecimal(linePayload, 'discount');
        if (line.discount == null) {
            line.discount = 0;
        }

        line.lineTotal = (Decimal.valueOf(line.quantity) * line.unitPrice * (1 - line.discount))
            .setScale(2, RoundingMode.HALF_UP);

        return line;
    }

    private static String getString(Map<String, Object> source, String key) {
        Object value = source.get(key);
        return value == null ? null : String.valueOf(value);
    }

    private static Integer getInteger(Map<String, Object> source, String key) {
        Object value = source.get(key);
        if (value == null) {
            return null;
        }
        if (value instanceof Integer) {
            return (Integer) value;
        }
        if (value instanceof Long) {
            Long longValue = (Long) value;
            if (longValue > Integer.valueOf(2147483647) || longValue < Integer.valueOf(-2147483648)) {
                throw new PayloadException('Integer value is out of range.');
            }
            return Integer.valueOf(String.valueOf(longValue));
        }
        if (value instanceof Decimal) {
            Decimal decimalValue = (Decimal) value;
            if (decimalValue.scale() != 0) {
                throw new PayloadException('Integer value must not contain decimals.');
            }
            return decimalValue.intValue();
        }
        throw new PayloadException('Integer value expected.');
    }

    private static Decimal getDecimal(Map<String, Object> source, String key) {
        Object value = source.get(key);
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        }
        throw new PayloadException('Decimal value expected.');
    }
}
