public with sharing class PicklistService {
    public class PicklistServiceException extends Exception {
    }

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        try {
            if (String.isBlank(objectApiName)) {
                throw new PicklistServiceException('Object API name is required.');
            }
            if (String.isBlank(fieldApiName)) {
                throw new PicklistServiceException('Field API name is required.');
            }

            Schema.SObjectType objectType = findObjectType(objectApiName);
            if (objectType == null) {
                throw new PicklistServiceException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
            Schema.SObjectField fieldToken = findFieldToken(objectDescribe, fieldApiName);
            if (fieldToken == null) {
                throw new PicklistServiceException(
                    'Field does not exist on object ' + objectDescribe.getName() + ': ' + fieldApiName
                );
            }

            Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
            Schema.DisplayType fieldType = fieldDescribe.getType();
            if (fieldType != Schema.DisplayType.Picklist && fieldType != Schema.DisplayType.MultiPicklist) {
                throw new PicklistServiceException(
                    'Field is not a picklist or multi-select picklist: ' +
                    objectDescribe.getName() + '.' + fieldDescribe.getName()
                );
            }

            List<PicklistService.Option> options = new List<PicklistService.Option>();
            for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
                if (entry.isActive()) {
                    options.add(new PicklistService.Option(
                        entry.getValue(),
                        entry.getLabel(),
                        entry.isDefaultValue()
                    ));
                }
            }

            return options;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException(e.getMessage());
        }
    }

    private static Schema.SObjectType findObjectType(String objectApiName) {
        String requestedName = objectApiName.trim();
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();

        Schema.SObjectType exactMatch = globalDescribe.get(requestedName);
        if (exactMatch != null) {
            return exactMatch;
        }

        String requestedNameLower = requestedName.toLowerCase();
        for (String candidateName : globalDescribe.keySet()) {
            if (candidateName != null && candidateName.toLowerCase() == requestedNameLower) {
                return globalDescribe.get(candidateName);
            }
        }

        return null;
    }

    private static Schema.SObjectField findFieldToken(
        Schema.DescribeSObjectResult objectDescribe,
        String fieldApiName
    ) {
        String requestedName = fieldApiName.trim();
        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();

        Schema.SObjectField exactMatch = fieldMap.get(requestedName);
        if (exactMatch != null) {
            return exactMatch;
        }

        String requestedNameLower = requestedName.toLowerCase();
        for (String candidateName : fieldMap.keySet()) {
            if (candidateName != null && candidateName.toLowerCase() == requestedNameLower) {
                return fieldMap.get(candidateName);
            }
        }

        return null;
    }
}
