public without sharing class AccountScoringJob implements Queueable {
    private static final Integer BATCH_SIZE = 200;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null ? new List<Id>() : new List<Id>(accountIds);
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer processCount = Math.min(BATCH_SIZE, accountIds.size());

        Set<Id> idsToProcess = new Set<Id>();
        for (Integer i = 0; i < processCount; i++) {
            if (accountIds[i] != null) {
                idsToProcess.add(accountIds[i]);
            }
        }

        List<Account> accountsToUpdate = new List<Account>();

        if (!idsToProcess.isEmpty()) {
            for (Account accountRecord : [
                SELECT Id, AnnualRevenue
                FROM Account
                WHERE Id IN :idsToProcess
            ]) {
                if (accountRecord.AnnualRevenue >= 1000000) {
                    accountRecord.Rating = 'Hot';
                } else if (accountRecord.AnnualRevenue >= 100000) {
                    accountRecord.Rating = 'Warm';
                } else {
                    accountRecord.Rating = 'Cold';
                }

                accountsToUpdate.add(accountRecord);
            }
        }

        update accountsToUpdate;

        if (accountIds.size() > processCount) {
            List<Id> remainingIds = new List<Id>();
            for (Integer i = processCount; i < accountIds.size(); i++) {
                remainingIds.add(accountIds[i]);
            }

            if (Test.isRunningTest()) {
                new AccountScoringJob(remainingIds).execute(context);
            } else {
                System.enqueueJob(new AccountScoringJob(remainingIds));
            }
        }
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }

        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
