public without sharing class OpportunityPipelineHandler {
    private static Boolean isHandling = false;

    public static void handle() {
        if (isHandling) {
            return;
        }

        isHandling = true;
        try {
            Set<Id> accountIds = new Set<Id>();

            if (Trigger.isInsert || Trigger.isUndelete) {
                collectAccountIdsFromNew(accountIds);
            } else if (Trigger.isDelete) {
                collectAccountIdsFromOld(accountIds);
            } else if (Trigger.isUpdate) {
                collectAffectedAccountIdsFromUpdate(accountIds);
            }

            if (!accountIds.isEmpty()) {
                recalculateAccounts(accountIds);
            }
        } finally {
            isHandling = false;
        }
    }

    private static void collectAccountIdsFromNew(Set<Id> accountIds) {
        for (Opportunity opp : (List<Opportunity>) Trigger.new) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    }

    private static void collectAccountIdsFromOld(Set<Id> accountIds) {
        for (Opportunity opp : (List<Opportunity>) Trigger.old) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    }

    private static void collectAffectedAccountIdsFromUpdate(Set<Id> accountIds) {
        Map<Id, Opportunity> oldMap = (Map<Id, Opportunity>) Trigger.oldMap;

        for (Opportunity newOpp : (List<Opportunity>) Trigger.new) {
            Opportunity oldOpp = oldMap.get(newOpp.Id);

            Boolean accountChanged = newOpp.AccountId != oldOpp.AccountId;
            Boolean amountChanged = newOpp.Amount != oldOpp.Amount;
            Boolean openClosedChanged = newOpp.IsClosed != oldOpp.IsClosed;

            if (accountChanged || amountChanged || openClosedChanged) {
                if (newOpp.AccountId != null) {
                    accountIds.add(newOpp.AccountId);
                }
                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }
    }

    private static void recalculateAccounts(Set<Id> accountIds) {
        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();

        for (Id accountId : accountIds) {
            accountsToUpdate.put(accountId, new Account(
                Id = accountId,
                FB_Open_Pipeline__c = 0,
                FB_Open_Opportunities__c = 0
            ));
        }

        for (AggregateResult result : [
            SELECT AccountId accountId,
                   SUM(Amount) totalAmount,
                   COUNT(Id) opportunityCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('accountId');

            accountsToUpdate.put(accountId, new Account(
                Id = accountId,
                FB_Open_Pipeline__c = (Decimal) result.get('totalAmount'),
                FB_Open_Opportunities__c = (Integer) result.get('opportunityCount')
            ));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }
}
