public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> results = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return results;
        }

        for (Id accountId : accountIds) {
            results.put(accountId, 0);
        }

        Date startOfYear = Date.newInstance(Date.today().year(), 1, 1);
        Date startOfNextYear = Date.newInstance(Date.today().year() + 1, 1, 1);

        for (AggregateResult aggregateRow : [
            SELECT AccountId accountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
                AND IsWon = true
                AND CloseDate >= :startOfYear
                AND CloseDate < :startOfNextYear
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) aggregateRow.get('accountId');
            Decimal totalAmount = (Decimal) aggregateRow.get('totalAmount');

            results.put(accountId, totalAmount == null ? 0 : totalAmount);
        }

        return results;
    }
}
