public with sharing class Opportunities extends fflib_SObjectDomain {
    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities((List<Opportunity>) records);
        }
    }

    public override void onAfterInsert() {
        startFulfilmentForClosedWonOpportunities(null);
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        startFulfilmentForClosedWonOpportunities((Map<Id, Opportunity>) existingRecords);
    }

    private void startFulfilmentForClosedWonOpportunities(Map<Id, Opportunity> existingRecords) {
        Set<Id> qualifyingOpportunityIds = new Set<Id>();

        for (Opportunity opportunityRecord : (List<Opportunity>) Records) {
            Boolean isClosedWon = opportunityRecord.StageName == 'Closed Won';

            if (!isClosedWon) {
                continue;
            }

            if (existingRecords == null) {
                qualifyingOpportunityIds.add(opportunityRecord.Id);
                continue;
            }

            Opportunity existingOpportunity = existingRecords.get(opportunityRecord.Id);
            if (existingOpportunity == null || existingOpportunity.StageName != 'Closed Won') {
                qualifyingOpportunityIds.add(opportunityRecord.Id);
            }
        }

        if (!qualifyingOpportunityIds.isEmpty()) {
            IOpportunityFulfilmentService fulfilmentService =
                (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);

            fulfilmentService.startFulfilment(qualifyingOpportunityIds);
        }
    }
}
