        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(opportunityIds);

        List<Opportunity> opportunitiesToClose = new List<Opportunity>();
        for (Opportunity opportunityRecord : opportunities) {
            if (opportunityRecord.StageName == 'Closed Won') {
                continue;
            }

            opportunityRecord.StageName = 'Closed Won';
            opportunityRecord.CloseDate = Date.today();
            opportunitiesToClose.add(opportunityRecord);
        }

        if (opportunitiesToClose.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork unitOfWork = Application.UnitOfWork.newInstance();

        for (Opportunity opportunityRecord : opportunitiesToClose) {
            unitOfWork.registerDirty(opportunityRecord);
            unitOfWork.registerPublishAfterSuccess(
                new Deal_Won__e(
                    Opportunity_Id__c = (String) opportunityRecord.Id,
                    Amount__c = opportunityRecord.Amount
                )
            );
        }

        unitOfWork.commitWork();

        return opportunitiesToClose.size();
    }
}
