public with sharing class PipelineSummary {
    private static final List<String> MANAGED_STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();

        for (String stageName : MANAGED_STAGES) {
            totals.put(stageName, 0);
        }

        if (fromDate == null || toDate == null || fromDate > toDate) {
            return totals;
        }

        for (AggregateResult result : [
            SELECT StageName stageName, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE StageName IN :MANAGED_STAGES
            AND CloseDate >= :fromDate
            AND CloseDate <= :toDate
            GROUP BY StageName
        ]) {
            totals.put(
                (String) result.get('stageName'),
                (Decimal) result.get('totalAmount')
            );
        }

        return totals;
    }
}
