public with sharing class ErpCustomerSync {
    private static final Integer MAX_CUSTOMERS_PER_REQUEST = 200;

    public class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;

        public CustomerPayload(Account accountRecord) {
            this.salesforceId = String.valueOf(accountRecord.Id);
            this.name = accountRecord.Name;
            this.country = accountRecord.BillingCountry;
        }
    }

    public static void enqueue(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        System.enqueueJob(new SendCustomersQueueable(new List<Account>(accounts)));
    }

    private class SendCustomersQueueable implements Queueable, Database.AllowsCallouts {
        private final List<Account> accounts;

        private SendCustomersQueueable(List<Account> accounts) {
            this.accounts = accounts;
        }

        public void execute(QueueableContext context) {
            List<CustomerPayload> customers = new List<CustomerPayload>();

            for (Account accountRecord : accounts) {
                customers.add(new CustomerPayload(accountRecord));

                if (customers.size() == MAX_CUSTOMERS_PER_REQUEST) {
                    sendCustomers(customers);
                    customers.clear();
                }
            }

            if (!customers.isEmpty()) {
                sendCustomers(customers);
            }
        }

        private static void sendCustomers(List<CustomerPayload> customers) {
            HttpRequest request = new HttpRequest();
            request.setEndpoint('callout:ERP/api/customers');
            request.setMethod('POST');
            request.setHeader('Content-Type', 'application/json');
            request.setBody(JSON.serialize(customers));

            Http http = new Http();
            HttpResponse response = http.send(request);

            // ERP returns 202 Accepted. Error handling and retries are out of scope for this ticket.
        }
    }
}
