                continue;
            }

            tasksToInsert.add(new Task(
                WhatId = opportunity.Id,
                OwnerId = opportunity.OwnerId,
                Subject = 'Follow up: ' + opportunity.Name,
                ActivityDate = Date.today().addDays(7),
                Status = 'Not Started',
                Priority = 'Normal'
            ));
            taskOpportunityIds.add(opportunity.Id);
