public with sharing class AccountRatingService {
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Set<Id> cleanAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                cleanAccountIds.add(accountId);
            }
        }

        if (cleanAccountIds.isEmpty()) {
            return;
        }

        Map<Id, AccountRatingSummary> summariesByAccountId = new Map<Id, AccountRatingSummary>();
        for (Id accountId : cleanAccountIds) {
            summariesByAccountId.put(accountId, new AccountRatingSummary());
        }

        for (AggregateResult result : [
            SELECT AccountId accountId,
                   COUNT(Id) openCount,
                   MAX(Amount) maxAmount
            FROM Opportunity
            WHERE AccountId IN :cleanAccountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('accountId');
            AccountRatingSummary summary = summariesByAccountId.get(accountId);
            summary.openCount = (Integer) result.get('openCount');
            summary.maxAmount = (Decimal) result.get('maxAmount');
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account accountRecord : [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :cleanAccountIds
        ]) {
            AccountRatingSummary summary = summariesByAccountId.get(accountRecord.Id);

            String newRating;
            if (summary == null || summary.openCount == 0) {
                newRating = 'Cold';
            } else if (summary.maxAmount != null && summary.maxAmount >= 100000) {
                newRating = 'Hot';
            } else {
                newRating = 'Warm';
            }

            if (accountRecord.Rating != newRating) {
                accountsToUpdate.add(new Account(
                    Id = accountRecord.Id,
                    Rating = newRating
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private class AccountRatingSummary {
        Integer openCount = 0;
        Decimal maxAmount;
    }
}
