public with sharing class LeadContactMatcher {
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> matchedContactIds = new List<Id>();

        if (leads == null || leads.isEmpty()) {
            return matchedContactIds;
        }

        Map<String, Id> firstContactIdByNormalizedEmail = new Map<String, Id>();

        if (contacts != null) {
            for (Contact contactRecord : contacts) {
                if (contactRecord == null || String.isBlank(contactRecord.Email)) {
                    continue;
                }

                String normalizedEmail = normalizeEmail(contactRecord.Email);

                if (!firstContactIdByNormalizedEmail.containsKey(normalizedEmail)) {
                    firstContactIdByNormalizedEmail.put(normalizedEmail, contactRecord.Id);
                }
            }
        }

        for (Lead leadRecord : leads) {
            if (leadRecord == null || String.isBlank(leadRecord.Email)) {
                matchedContactIds.add(null);
                continue;
            }

            matchedContactIds.add(firstContactIdByNormalizedEmail.get(normalizeEmail(leadRecord.Email)));
        }

        return matchedContactIds;
    }

    private static String normalizeEmail(String email) {
        return email.trim().toLowerCase();
    }
}
