import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    results = [];
    errorMessage;

    debounceTimeout;
    latestRequestId = 0;
    isConnectedToDom = false;

    connectedCallback() {
        this.isConnectedToDom = true;
    }

    disconnectedCallback() {
        this.isConnectedToDom = false;
        this.clearPendingSearch();
    }

    handleChange(event) {
        const searchTerm = (event.target.value || '').trim();

        this.clearPendingSearch();

        if (searchTerm.length < 2) {
            this.results = [];
            this.errorMessage = undefined;
            return;
        }

        this.debounceTimeout = window.setTimeout(() => {
            this.debounceTimeout = undefined;

            if (!this.isConnectedToDom) {
                return;
            }

            const requestId = ++this.latestRequestId;

            searchContacts({ searchTerm })
                .then((contacts) => {
                    if (this.isLatestActiveRequest(requestId)) {
                        this.results = contacts;
                        this.errorMessage = undefined;
                    }
                })
                .catch((error) => {
                    if (this.isLatestActiveRequest(requestId)) {
                        this.results = [];
                        this.errorMessage = error?.body?.message;
                    }
                });
        }, 300);
    }

    clearPendingSearch() {
        if (this.debounceTimeout) {
            window.clearTimeout(this.debounceTimeout);
            this.debounceTimeout = undefined;
        }
    }

    isLatestActiveRequest(requestId) {
        return this.isConnectedToDom && requestId === this.latestRequestId;
    }
}
