import { LightningElement, wire } from 'lwc';
import {
    APPLICATION_SCOPE,
    MessageContext,
    publish,
    subscribe,
    unsubscribe
} from 'lightning/messageService';
import ACCOUNT_SELECTED_CHANNEL from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    @wire(MessageContext)
    messageContext;

    recordId;
    subscription = null;

    connectedCallback() {
        this.subscribeToAccountSelected();
    }

    disconnectedCallback() {
        this.unsubscribeFromAccountSelected();
    }

    subscribeToAccountSelected() {
        if (this.subscription) {
            return;
        }

        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED_CHANNEL,
            (message) => this.handleAccountSelected(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    unsubscribeFromAccountSelected() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    handleAccountSelected(message) {
        this.recordId = message?.recordId || null;
    }

    handleClear() {
        publish(this.messageContext, ACCOUNT_SELECTED_CHANNEL, { recordId: null });
    }
}
