const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    errorMessage;

    intervalId;
    isLoading = false;
    isConnectedComponent = false;

    boundHandleVisibilityChange = this.handleVisibilityChange.bind(this);

    connectedCallback() {
        if (this.isConnectedComponent) {
            return;
        }

        this.isConnectedComponent = true;
        document.addEventListener('visibilitychange', this.boundHandleVisibilityChange);

        if (document.visibilityState !== 'hidden') {
            this.loadStats();
        }

        this.startPolling();
    }

    disconnectedCallback() {
        this.isConnectedComponent = false;
        this.stopPolling();
        document.removeEventListener('visibilitychange', this.boundHandleVisibilityChange);
    }

    get hasStats() {
        return this.waiting !== undefined && this.longestWaitMinutes !== undefined;
    }

    async loadStats() {
        if (!this.isConnectedComponent || this.isLoading || document.visibilityState === 'hidden') {
            return;
        }

        this.isLoading = true;

        try {
            const stats = await getQueueStats();

            if (!this.isConnectedComponent) {
                return;
            }

            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.errorMessage = undefined;
        } catch (error) {
            if (!this.isConnectedComponent) {
                return;
            }

            this.errorMessage = error?.body?.message || 'An unexpected error occurred.';
        } finally {
            this.isLoading = false;
        }
    }

    startPolling() {
        this.stopPolling();

        this.intervalId = window.setInterval(() => {
            this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this.intervalId) {
            window.clearInterval(this.intervalId);
            this.intervalId = undefined;
        }
    }

    handleVisibilityChange() {
        if (!this.isConnectedComponent) {
            return;
        }

        if (document.visibilityState === 'hidden') {
            return;
        }

        this.loadStats();
    }
}
