import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    _label = '';
    _options = [];
    _value = '';
    _activeValue = '';

    optionIdPrefix = `status-listbox-option-${Math.random().toString(36).slice(2)}`;

    @api
    get label() {
        return this._label;
    }

    set label(value) {
        this._label = value || '';
    }

    @api
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        this.syncActiveOption();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value || '';
        this.syncActiveOption();
    }

    get computedOptions() {
        return this._options.map((option, index) => {
            const optionValue = option.value;
            const isSelected = optionValue === this._value;

            return {
                value: optionValue,
                label: option.label,
                id: this.getOptionId(index),
                ariaSelected: isSelected ? 'true' : 'false'
            };
        });
    }

    get activeDescendant() {
        const activeIndex = this.activeIndex;
        return activeIndex >= 0 ? this.getOptionId(activeIndex) : null;
    }

    get activeIndex() {
        return this._options.findIndex((option) => option.value === this._activeValue);
    }

    syncActiveOption() {
        if (!this._options.length) {
            this._activeValue = '';
            return;
        }

        const selectedOption = this._options.find((option) => option.value === this._value);

        if (selectedOption) {
            this._activeValue = selectedOption.value;
            return;
        }

        const activeOptionStillExists = this._options.some(
            (option) => option.value === this._activeValue
        );

        if (!activeOptionStillExists) {
            this._activeValue = this._options[0].value;
        }
    }

    getOptionId(index) {
        return `${this.optionIdPrefix}-${index}`;
    }

    handleKeydown(event) {
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (!handledKeys.includes(event.key)) {
            return;
        }

        event.preventDefault();

        if (!this._options.length) {
            return;
        }

        switch (event.key) {
            case 'ArrowDown':
                this.moveActiveOption(1);
                break;
            case 'ArrowUp':
                this.moveActiveOption(-1);
                break;
            case 'Home':
                this.setActiveIndex(0);
                break;
            case 'End':
                this.setActiveIndex(this._options.length - 1);
                break;
            case 'Enter':
            case ' ':
                this.selectValue(this._activeValue);
                break;
            default:
        }
    }

    handleClick(event) {
        const value = event.currentTarget.dataset.value;
        this._activeValue = value;
        this.selectValue(value);
    }

    moveActiveOption(delta) {
        const currentIndex = this.activeIndex;
        const startingIndex = currentIndex >= 0 ? currentIndex : 0;
        const nextIndex = Math.max(
            0,
            Math.min(this._options.length - 1, startingIndex + delta)
        );

        this.setActiveIndex(nextIndex);
    }

    setActiveIndex(index) {
        const option = this._options[index];

        if (option) {
            this._activeValue = option.value;
        }
    }

    selectValue(value) {
        if (value === this._value) {
            return;
        }

        this._value = value;

        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value }
            })
        );
    }
}
