import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading = '';
    _tasks = [];

    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get heading() {
        return this._heading;
    }

    set heading(value) {
        this._heading = value ?? '';
    }

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = Array.isArray(value) ? value : [];
        this.items = this._tasks.map((task) => ({ ...task }));
    }

    get displayHeading() {
        return this._heading ? this._heading.toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();

        if (!label) {
            return;
        }

        this.items = [
            ...this.items,
            {
                id: `new-${this.nextId++}`,
                label,
                done: false
            }
        ];

        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const taskId = event.target.dataset.id;
        const checked = event.target.checked;

        this.items = this.items.map((task) =>
            String(task.id) === String(taskId) ? { ...task, done: checked } : task
        );
    }
}
