public with sharing class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        validateOpportunityId(opportunityId);
        validatePercentMap(percentByGauId);

        Set<Id> gauIds = new Set<Id>(percentByGauId.keySet());

        Map<Id, npsp__General_Accounting_Unit__c> gauById = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIds
        ]);

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauById.get(gauId);
            if (gau == null || gau.npsp__Active__c != true) {
                throw new AllocationException('All GAUs must exist and be active.');
            }
        }

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        List<npsp__Allocation__c> allocationsToInsert = new List<npsp__Allocation__c>();
        for (Id gauId : gauIds) {
            allocationsToInsert.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        insert allocationsToInsert;

        return allocationsToInsert;
    }

    private static void validateOpportunityId(Id opportunityId) {
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required.');
        }

        Schema.SObjectType opportunityType = Opportunity.SObjectType;
        if (opportunityId.getSObjectType() != opportunityType) {
            throw new AllocationException('Id must be an Opportunity Id.');
        }
    }

    private static void validatePercentMap(Map<Id, Decimal> percentByGauId) {
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU percentage is required.');
        }

        Decimal totalPercent = 0;

        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('GAU Id cannot be null.');
            }

            if (gauId.getSObjectType() != npsp__General_Accounting_Unit__c.SObjectType) {
                throw new AllocationException('All keys must be GAU Ids.');
            }

            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException('Each percentage must be greater than 0.');
            }

            totalPercent += percent;
        }

        if (totalPercent > 100) {
            throw new AllocationException('Total percentage cannot exceed 100.');
        }
    }
}
