    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        Id householdRecordTypeId = Schema.SObjectType.Account
            .getRecordTypeInfosByDeveloperName()
            .get('HH_Account')
            .getRecordTypeId();

        Account household = new Account(
            RecordTypeId = householdRecordTypeId
        );
        insert household;

        List<Contact> contactsToInsert = new List<Contact>();
        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException('members must not contain null contacts');
            }

            Contact contactToInsert = member.clone(false, true, false, false);
            contactToInsert.AccountId = household.Id;
            contactsToInsert.add(contactToInsert);
        }

        insert contactsToInsert;

        household.npe01__One2OneContact__c = contactsToInsert[0].Id;
        update household;

        return household.Id;
    }
}
