            this.opportunityId = opportunityId;
            this.contactId = contactId;
        }

        public Boolean equals(Object other) {
            if (!(other instanceof OppContactKey)) {
                return false;
            }

            OppContactKey otherKey = (OppContactKey) other;
            return opportunityId == otherKey.opportunityId && contactId == otherKey.contactId;
        }

        public Integer hashCode() {
            Integer result = 17;
            result = 31 * result + (opportunityId == null ? 0 : String.valueOf(opportunityId).hashCode());
            result = 31 * result + (contactId == null ? 0 : String.valueOf(contactId).hashCode());
            return result;
        }
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<OppContactKey> requestedKeys = new Set<OppContactKey>();

        for (SoftCreditRequest request : requests) {
            if (request == null) {
                throw new SoftCreditException('Soft credit request cannot be null.');
            }

            if (request.opportunityId == null) {
                throw new SoftCreditException('Opportunity Id is required.');
            }

            if (request.contactId == null) {
                throw new SoftCreditException('Contact Id is required.');
            }

            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);
            requestedKeys.add(new OppContactKey(request.opportunityId, request.contactId));
        }

        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]);

        for (SoftCreditRequest request : requests) {
            Opportunity opp = opportunitiesById.get(request.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + String.valueOf(request.opportunityId));
            }

            if (request.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('Primary contact cannot receive a partial soft credit for opportunity ' + String.valueOf(request.opportunityId) + '.');
            }

            if (request.amount == null || request.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be positive for opportunity ' + String.valueOf(request.opportunityId) + '.');
            }

            if (opp.Amount != null && request.amount > opp.Amount) {
                throw new SoftCreditException('Soft credit amount cannot be greater than opportunity amount for opportunity ' + String.valueOf(request.opportunityId) + '.');
            }
        }

        Map<OppContactKey, List<OpportunityContactRole>> existingRolesByKey = new Map<OppContactKey, List<OpportunityContactRole>>();

        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
            AND ContactId IN :contactIds
        ]) {
            OppContactKey key = new OppContactKey(ocr.OpportunityId, ocr.ContactId);
            if (!existingRolesByKey.containsKey(key)) {
                existingRolesByKey.put(key, new List<OpportunityContactRole>());
            }
            existingRolesByKey.get(key).add(ocr);
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();
        Map<OppContactKey, OpportunityContactRole> desiredRoleByKey = new Map<OppContactKey, OpportunityContactRole>();

        for (SoftCreditRequest request : requests) {
            OppContactKey key = new OppContactKey(request.opportunityId, request.contactId);
            List<OpportunityContactRole> existingRoles = existingRolesByKey.get(key);

            if (existingRoles == null || existingRoles.isEmpty()) {
                OpportunityContactRole roleToInsert = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role
                );
                rolesToInsert.add(roleToInsert);
                desiredRoleByKey.put(key, roleToInsert);
            } else {
                OpportunityContactRole roleToKeep = existingRoles[0];

                if (roleToKeep.Role != request.role) {
                    roleToKeep.Role = request.role;
                    rolesToUpdate.add(roleToKeep);
                }

                desiredRoleByKey.put(key, roleToKeep);

                for (Integer i = 1; i < existingRoles.size(); i++) {
                    rolesToDelete.add(existingRoles[i]);
                }
            }
        }

        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }

        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }

        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }

        Map<OppContactKey, npsp__Partial_Soft_Credit__c> existingSoftCreditsByKey = new Map<OppContactKey, npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> duplicateSoftCreditsToDelete = new List<npsp__Partial_Soft_Credit__c>();

        for (npsp__Partial_Soft_Credit__c softCredit : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c, npsp__Role_Name__c,
                   npsp__Contact_Role_ID__c, npsp__Contact_Name__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
            AND npsp__Contact__c IN :contactIds
        ]) {
            OppContactKey key = new OppContactKey(softCredit.npsp__Opportunity__c, softCredit.npsp__Contact__c);

            if (requestedKeys.contains(key) && !existingSoftCreditsByKey.containsKey(key)) {
                existingSoftCreditsByKey.put(key, softCredit);
            } else if (requestedKeys.contains(key)) {
                duplicateSoftCreditsToDelete.add(softCredit);
            }
        }

        List<npsp__Partial_Soft_Credit__c> softCreditsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> softCreditsToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            OppContactKey key = new OppContactKey(request.opportunityId, request.contactId);
            OpportunityContactRole contactRole = desiredRoleByKey.get(key);

            npsp__Partial_Soft_Credit__c softCredit = existingSoftCreditsByKey.get(key);
            if (softCredit == null) {
                softCredit = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = request.opportunityId,
                    npsp__Contact__c = request.contactId,
                    npsp__Contact_Name__c = request.contactId
                );
                softCreditsToInsert.add(softCredit);
            } else {
                softCreditsToUpdate.add(softCredit);
            }

            softCredit.npsp__Amount__c = request.amount;
            softCredit.npsp__Role_Name__c = request.role;
            softCredit.npsp__Contact_Role_ID__c = String.valueOf(contactRole.Id);
        }

        if (!duplicateSoftCreditsToDelete.isEmpty()) {
            delete duplicateSoftCreditsToDelete;
        }

        if (!softCreditsToUpdate.isEmpty()) {
            update softCreditsToUpdate;
        }

        if (!softCreditsToInsert.isEmpty()) {
            insert softCreditsToInsert;
        }
    }
}
