public with sharing class FamilyService {
    private static final String PARENT_TYPE = 'Parent';
    private static final String CURRENT_STATUS = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Map<Id, Id> cleanedParentIdByChildId = new Map<Id, Id>();
        Set<Id> contactIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            cleanedParentIdByChildId.put(childId, parentId);
            contactIds.add(childId);
            contactIds.add(parentId);
        }

        if (cleanedParentIdByChildId.isEmpty()) {
            return;
        }

        Set<String> requestedPairKeys = new Set<String>();
        for (Id childId : cleanedParentIdByChildId.keySet()) {
            requestedPairKeys.add(unorderedPairKey(childId, cleanedParentIdByChildId.get(childId)));
        }

        Set<String> existingPairKeys = new Set<String>();

        for (npe4__Relationship__c relationshipRecord : [
            SELECT Id, npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
            AND npe4__RelatedContact__c IN :contactIds
        ]) {
            if (relationshipRecord.npe4__Contact__c == null || relationshipRecord.npe4__RelatedContact__c == null) {
                continue;
            }

            String existingKey = unorderedPairKey(
                relationshipRecord.npe4__Contact__c,
                relationshipRecord.npe4__RelatedContact__c
            );

            if (requestedPairKeys.contains(existingKey)) {
                existingPairKeys.add(existingKey);
            }
        }

        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();

        for (Id childId : cleanedParentIdByChildId.keySet()) {
            Id parentId = cleanedParentIdByChildId.get(childId);
            String pairKey = unorderedPairKey(childId, parentId);

            if (existingPairKeys.contains(pairKey)) {
                continue;
            }

            /*
             * NPSP's default "List Setting" reciprocal method uses the active
             * Relationship Lookup named in npe4__Type__c to create the reciprocal
             * relationship automatically. Creating Parent from child -> parent causes
             * the reciprocal parent -> child type to be Son, Daughter, or Child
             * according to the configured lookup.
             */
            relationshipsToInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = PARENT_TYPE,
                npe4__Status__c = CURRENT_STATUS
            ));

            /*
             * If duplicate child -> parent pairs were supplied through overwrite in
             * the input Map this set update is harmless; if multiple children share
             * the same parent each unordered key remains distinct.
             */
            existingPairKeys.add(pairKey);
        }

        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }

    private static String unorderedPairKey(Id firstId, Id secondId) {
        String first = String.valueOf(firstId);
        String second = String.valueOf(secondId);

        return first < second
            ? first + ':' + second
            : second + ':' + first;
    }
}
