public without sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {
    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        List<Task> tasksToInsert = new List<Task>();

        Map<Id, Opportunity> oldOppsById = new Map<Id, Opportunity>();
        if (oldlist != null) {
            for (SObject oldRecord : oldlist) {
                Opportunity oldOpp = (Opportunity) oldRecord;
                oldOppsById.put(oldOpp.Id, oldOpp);
            }
        }

        for (SObject newRecord : newlist) {
            Opportunity opp = (Opportunity) newRecord;

            Boolean nowQualifies = isMajorClosedWonGift(opp);
            if (!nowQualifies) {
                continue;
            }

            Boolean previouslyQualified = false;
            if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                Opportunity oldOpp = oldOppsById.get(opp.Id);
                previouslyQualified = oldOpp != null && isMajorClosedWonGift(oldOpp);
            }

            if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert || !previouslyQualified) {
                tasksToInsert.add(new Task(
                    Subject = 'Major gift thank-you call',
                    Priority = 'High',
                    Status = 'Not Started',
                    WhatId = opp.Id,
                    WhoId = opp.npsp__Primary_Contact__c,
                    OwnerId = opp.OwnerId,
                    ActivityDate = opp.CloseDate == null ? null : opp.CloseDate.addDays(3)
                ));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return new npsp.TDTM_Runnable.DmlWrapper();
    }

    private static Boolean isMajorClosedWonGift(Opportunity opp) {
        return opp != null
            && opp.IsWon == true
            && opp.Amount != null
            && opp.Amount >= 5000;
    }
}
