public with sharing class RecordAccessService {
    private static final Integer USER_RECORD_ACCESS_MAX_RECORDS_PER_QUERY = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editableRecordIds = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editableRecordIds;
        }

        Id currentUserId = UserInfo.getUserId();

        /*
         * UserRecordAccess supports checking multiple records via RecordId IN :ids,
         * but the list is limited to 200 record IDs per query. Callers may pass up
         * to 2,000 IDs, so chunk into 200-ID batches: at most 10 SOQL queries.
         *
         * Querying UserRecordAccess is the platform-supported way to include CRUD,
         * ownership, sharing, role hierarchy, teams, manual shares, territories,
         * View All/Modify All, and other access grants in one check.
         */
        List<Id> idsToCheck = new List<Id>(recordIds);

        for (Integer startIndex = 0; startIndex < idsToCheck.size(); startIndex += USER_RECORD_ACCESS_MAX_RECORDS_PER_QUERY) {
            Set<Id> batchIds = new Set<Id>();

            Integer endIndex = Math.min(startIndex + USER_RECORD_ACCESS_MAX_RECORDS_PER_QUERY, idsToCheck.size());
            for (Integer i = startIndex; i < endIndex; i++) {
                batchIds.add(idsToCheck[i]);
            }

            for (UserRecordAccess accessRow : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :currentUserId
                AND RecordId IN :batchIds
            ]) {
                if (accessRow.HasEditAccess) {
                    editableRecordIds.add(accessRow.RecordId);
                }
            }
        }

        return editableRecordIds;
    }
}
