@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    @IsTest
    static void reductionOfMoreThanHalfIsRejected() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpp = new Opportunity(
            Id = oppId,
            Amount = 1000
        );
        Opportunity newOpp = new Opportunity(
            Id = oppId,
            Amount = 499
        );

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        System.assert(newOpp.hasErrors(), 'A reduction of more than half should add an error.');

        List<Database.Error> errors = newOpp.getErrors();
        System.assertEquals(1, errors.size(), 'Exactly one error should be added.');
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            'The error message should match the action constant.'
        );
    }

    @IsTest
    static void reductionsOfHalfOrLessAndIncreasesAreAccepted() {
        Id halfReductionOppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldHalfReductionOpp = new Opportunity(
            Id = halfReductionOppId,
            Amount = 1000
        );
        Opportunity newHalfReductionOpp = new Opportunity(
            Id = halfReductionOppId,
            Amount = 500
        );

        Id increaseOppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldIncreaseOpp = new Opportunity(
            Id = increaseOppId,
            Amount = 1000
        );
        Opportunity newIncreaseOpp = new Opportunity(
            Id = increaseOppId,
            Amount = 1500
        );

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{
                newHalfReductionOpp,
                newIncreaseOpp
            },
            new List<Opportunity>{
                oldHalfReductionOpp,
                oldIncreaseOpp
            }
        );

        System.assertEquals(
            false,
            newHalfReductionOpp.hasErrors(),
            'A reduction of exactly half should be accepted.'
        );
        System.assertEquals(
            0,
            newHalfReductionOpp.getErrors().size(),
            'A reduction of exactly half should not add any errors.'
        );

        System.assertEquals(
            false,
            newIncreaseOpp.hasErrors(),
            'An increase should be accepted.'
        );
        System.assertEquals(
            0,
            newIncreaseOpp.getErrors().size(),
            'An increase should not add any errors.'
        );
    }

    @IsTest
    static void previousNullAmountIsAcceptedWithoutException() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpp = new Opportunity(
            Id = oppId,
            Amount = null
        );
        Opportunity newOpp = new Opportunity(
            Id = oppId,
            Amount = 1
        );

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        System.assertEquals(
            false,
            newOpp.hasErrors(),
            'A record whose previous Amount was null should be accepted.'
        );
        System.assertEquals(
            0,
            newOpp.getErrors().size(),
            'A record whose previous Amount was null should not add any errors.'
        );
    }

    @IsTest
    static void mixedRecordsOnlyInvalidRecordsReceiveErrors() {
        Id invalidOppIdOne = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldInvalidOppOne = new Opportunity(
            Id = invalidOppIdOne,
            Amount = 1000
        );
        Opportunity newInvalidOppOne = new Opportunity(
            Id = invalidOppIdOne,
            Amount = 499
        );

        Id validOppIdOne = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldValidOppOne = new Opportunity(
            Id = validOppIdOne,
            Amount = 1000
        );
        Opportunity newValidOppOne = new Opportunity(
            Id = validOppIdOne,
            Amount = 500
        );

        Id validOppIdTwo = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldValidOppTwo = new Opportunity(
            Id = validOppIdTwo,
            Amount = 1000
        );
        Opportunity newValidOppTwo = new Opportunity(
            Id = validOppIdTwo,
            Amount = 1500
        );

        Id validOppIdThree = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldValidOppThree = new Opportunity(
            Id = validOppIdThree,
            Amount = null
        );
        Opportunity newValidOppThree = new Opportunity(
            Id = validOppIdThree,
            Amount = 1
        );

        Id invalidOppIdTwo = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldInvalidOppTwo = new Opportunity(
            Id = invalidOppIdTwo,
            Amount = 200
        );
        Opportunity newInvalidOppTwo = new Opportunity(
            Id = invalidOppIdTwo,
            Amount = 99
        );

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{
                newInvalidOppOne,
                newValidOppOne,
                newValidOppTwo,
                newValidOppThree,
                newInvalidOppTwo
            },
            new List<Opportunity>{
                oldInvalidOppOne,
                oldValidOppOne,
                oldValidOppTwo,
                oldValidOppThree,
                oldInvalidOppTwo
            }
        );

        assertSingleGuardError(newInvalidOppOne, 'The first invalid record should receive exactly one error.');
        assertNoErrors(newValidOppOne, 'The exactly-half reduction record should receive no errors.');
        assertNoErrors(newValidOppTwo, 'The increased Amount record should receive no errors.');
        assertNoErrors(newValidOppThree, 'The previous-null Amount record should receive no errors.');
        assertSingleGuardError(newInvalidOppTwo, 'The second invalid record should receive exactly one error.');
    }

    private static void assertSingleGuardError(Opportunity opp, String message) {
        System.assert(opp.hasErrors(), message);

        List<Database.Error> errors = opp.getErrors();
        System.assertEquals(1, errors.size(), message);
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            message
        );
    }

    private static void assertNoErrors(Opportunity opp, String message) {
        System.assertEquals(false, opp.hasErrors(), message);
        System.assertEquals(0, opp.getErrors().size(), message);
    }
}
