public inherited sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    private static final String ERROR_MESSAGE =
            'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validate(triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validate(triggerNew, triggerOld);
    }

    private static void validate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Map<Id, Contact> oldById = new Map<Id, Contact>();
        if (triggerOld != null) {
            for (SObject oldRecord : triggerOld) {
                Contact oldContact = (Contact) oldRecord;
                oldById.put(oldContact.Id, oldContact);
            }
        }

        List<Contact> contactsToCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> normalizedEmails = new Set<String>();
        Set<Id> triggerContactIds = new Set<Id>();

        for (SObject newRecord : triggerNew) {
            Contact contact = (Contact) newRecord;

            if (contact.Id != null) {
                triggerContactIds.add(contact.Id);
            }

            if (!shouldCheck(contact, oldById.get(contact.Id))) {
                continue;
            }

            contactsToCheck.add(contact);
            accountIds.add(contact.AccountId);
            normalizedEmails.add(normalizeEmail(contact.Email));
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        Set<String> existingAccountEmailKeys = new Set<String>();
        for (Contact existingContact : [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                AND Email != null
        ]) {
            if (triggerContactIds.contains(existingContact.Id)) {
                continue;
            }

            String normalizedEmail = normalizeEmail(existingContact.Email);
            if (normalizedEmails.contains(normalizedEmail)) {
                existingAccountEmailKeys.add(makeKey(existingContact.AccountId, normalizedEmail));
            }
        }

        Set<String> seenInThisSave = new Set<String>();
        for (Contact contact : contactsToCheck) {
            String key = makeKey(contact.AccountId, normalizeEmail(contact.Email));

            if (seenInThisSave.contains(key) || existingAccountEmailKeys.contains(key)) {
                contact.addError(ERROR_MESSAGE);
                continue;
            }

            seenInThisSave.add(key);
        }
    }

    private static Boolean shouldCheck(Contact newContact, Contact oldContact) {
        if (newContact.AccountId == null || String.isBlank(newContact.Email)) {
            return false;
        }

        if (oldContact == null) {
            return true;
        }

        return newContact.AccountId != oldContact.AccountId
                || newContact.Email != oldContact.Email;
    }

    private static String normalizeEmail(String email) {
        return email == null ? null : email.trim().toLowerCase();
    }

    private static String makeKey(Id accountId, String normalizedEmail) {
        return String.valueOf(accountId) + '|' + normalizedEmail;
    }
}
