public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static Set<Id> opportunityIdsLoggedThisTransaction = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        for (SObject oldRecord : triggerOld) {
            Opportunity oldOpportunity = (Opportunity) oldRecord;
            oldById.put(oldOpportunity.Id, oldOpportunity);
        }

        List<Task> tasksToInsert = new List<Task>();

        for (SObject newRecord : triggerNew) {
            Opportunity newOpportunity = (Opportunity) newRecord;
            Opportunity oldOpportunity = oldById.get(newOpportunity.Id);

            if (
                oldOpportunity != null &&
                newOpportunity.Amount != oldOpportunity.Amount &&
                !opportunityIdsLoggedThisTransaction.contains(newOpportunity.Id)
            ) {
                opportunityIdsLoggedThisTransaction.add(newOpportunity.Id);

                tasksToInsert.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = newOpportunity.Id,
                    Status = 'Completed'
                ));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
